const output = [];
const targets = { portrait: [1080, 1350], square: [1080, 1080], landscape: [1080, 566] };
for (const [inputIndex, input] of $input.all().entries()) {
  const raw = input.json.body?.metadata ?? input.json.metadata;
  const payload = typeof raw === 'string' ? JSON.parse(raw) : raw;
  if (!payload || payload.schemaVersion !== '1.0' || !Array.isArray(payload.content) || payload.content.length === 0 || payload.contentCount !== payload.content.length) {
    throw new Error('Expected Storiq schemaVersion 1.0 metadata with a non-empty content array and matching contentCount. Pass the complete Webhook item, including binary files.');
  }
  if (typeof payload.requestId !== 'string' || !payload.requestId || !['content.schedule', 'content.publish_now'].includes(payload.eventType)) {
    throw new Error('Missing requestId or unsupported Storiq eventType.');
  }
  for (const content of payload.content) {
    if (!content || !Array.isArray(content.platformTypes)) throw new Error('Each content item needs platformTypes.');
    if (!content.platformTypes.includes('instagram')) continue;
    const target = Object.hasOwn(targets, content.aspectRatio) ? targets[content.aspectRatio] : undefined;
    if (!target) throw new Error(`${content.fileName}: feed images require portrait, square, or landscape. Route Story media to a separate workflow.`);
    if (!['image/jpeg', 'image/png', 'image/webp'].includes(content.fileType)) {
      throw new Error(`${content.fileName}: this workflow accepts JPEG, PNG, and WebP feed images only. Route videos separately; convert other image formats before calling it.`);
    }
    const key = content.fileContent?.fieldName;
    if (content.fileContent?.transferType !== 'multipart_binary' || typeof key !== 'string' || !key) {
      throw new Error(`${content.fileName}: missing multipart binary field ${key}. Preserve Webhook binary data and its field names.`);
    }
    // n8n appends 0 when the multipart parser represents a field as a file array.
    const keys = [key, `${key}0`].filter((candidate) => Object.hasOwn(input.binary ?? {}, candidate));
    if (keys.length !== 1) throw new Error(`${content.fileName}: missing multipart binary field ${key}, or ambiguous file mapping. Expected exactly one of ${key} and ${key}0.`);
    const binary = input.binary[keys[0]];
    if (binary.mimeType !== content.fileType) throw new Error(`${content.fileName}: binary MIME type does not match the metadata.`);
    const baseName = (content.fileName || 'image').replace(/\.[^.]+$/, '');
    output.push({
      json: {
        requestId: payload.requestId, eventType: payload.eventType, publishMode: payload.publishMode,
        timezone: payload.timezone, content, targetWidth: target[0], targetHeight: target[1],
        outputFileName: `${baseName}-instagram-feed.jpg`
      },
      binary: { data: binary }, pairedItem: { item: inputIndex }
    });
  }
}
if (!output.length) throw new Error('No Instagram feed images found. Call this workflow only on the Instagram image branch.');
return output;

return $input.all().map((item, index) => {
  // Get Information replaces JSON; item linking restores the matching metadata.
  const source = $('Resize to Cover').itemMatching(index).json;
  const width = Number(item.json.size?.width);
  const height = Number(item.json.size?.height);
  if (!Number.isSafeInteger(width) || !Number.isSafeInteger(height) || width < source.targetWidth || height < source.targetHeight) {
    throw new Error(`${source.content.fileName}: resize did not cover the required ${source.targetWidth}x${source.targetHeight} canvas.`);
  }
  return {
    json: { ...source, cropX: Math.floor((width - source.targetWidth) / 2), cropY: Math.floor((height - source.targetHeight) / 2) },
    binary: item.binary, pairedItem: { item: index }
  };
});

const output = [];
for (const [index, item] of $input.all().entries()) {
  const source = $('Crop Instagram Feed').itemMatching(index).json;
  const width = Number(item.json.size?.width);
  const height = Number(item.json.size?.height);
  const ratio = width / height;
  if (width !== source.targetWidth || height !== source.targetHeight || !(ratio >= 0.8 && ratio <= 1.91) || item.json.format !== 'JPEG') {
    throw new Error(`${source.content.fileName}: final image failed JPEG/dimension/feed-ratio validation.`);
  }
  const buffer = await this.helpers.getBinaryDataBuffer(index, 'data');
  if (buffer.length < 3 || buffer[0] !== 0xff || buffer[1] !== 0xd8 || buffer[2] !== 0xff) {
    throw new Error(`${source.content.fileName}: output binary is not a JPEG.`);
  }
  if (buffer.length > 8 * 1024 * 1024) throw new Error(`${source.content.fileName}: JPEG exceeds the 8 MiB workflow limit. Reduce image quality before publishing.`);
  output.push({
    json: {
      ...source.content,
      requestId: source.requestId, eventType: source.eventType, publishMode: source.publishMode, timezone: source.timezone,
      sourcePlatformTypes: source.content.platformTypes, platformTypes: ['instagram'],
      originalFileName: source.content.fileName, fileName: source.outputFileName,
      fileType: 'image/jpeg', fileSizeBytes: buffer.length,
      fileContent: { transferType: 'n8n_binary', fieldName: 'data' },
      width, height, processedFor: 'instagram_feed'
    },
    binary: { data: { ...item.binary.data, fileName: source.outputFileName, mimeType: 'image/jpeg', fileExtension: 'jpg' } },
    pairedItem: { item: index }
  });
}
return output;
